# The cross-product relationship must hold: (c-c1)/(r-r1) == (c2-c1)/(r2-r1)

def point_on_line(r, c, p1, p2):
    r1, c1 = p1
    r2, c2 = p2

    # Handle degenerate cases
    if r1 == r2 and c1 == c2:
        return r == r1 and c == c1
    if r1 == r2:
        return r == r1
    if c1 == c2:
        return c == c1

    # Cross product test: (c - c1)(r2 - r1) == (r - r1)(c2 - c1)
    return (c - c1) * (r2 - r1) == (r - r1) * (c2 - c1)

